const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { customerId, userMessage, conversationHistory, cvAnalysis } = $input.first().json.body;
const cvContext = cvAnalysis ? JSON.stringify(cvAnalysis) : 'none';
const systemPrompt = `أنت وكيل مبيعات CVPro.ae (الإمارات). الأسعار: Essential 399 | LinkedIn 299 | Career Boost 599 | Executive 999 درهم. ردود قصيرة.\nتحليل CV: ${cvContext}\nالمحادثة:\n${conversationHistory}\nرسالة العميل: ${userMessage}`;
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const reply = await rotator.call(userMessage, systemPrompt, 300, 0.7);
return [{ json: { reply, customerId } }];
